//! Translated from linuxdoom-1.10/info.c and linuxdoom-1.10/info.h
//!
//! Thing frame/state LUT, generated by multigen utility.
//! This is the original DOOM version, preserved.
//!
//! The state table defines every animation frame in the game:
//! which sprite to display, how long to display it, what action
//! function to call, and what state to transition to next.
//!
//! Contains 967 state entries ([`NUMSTATES`]) covering:
//! - Weapon states (ready, fire, flash, lower, raise)
//! - Monster states (stand, run, attack, pain, death, raise)
//! - Projectile states (fly, impact, explosion)
//! - Item/pickup states (spawn, pickup flash)
//! - Environmental/decoration states (lamps, torches, gore)

use super::sprites::SpriteNum;

// ---------------------------------------------------------------------------
// StateNum enum (info.h lines 174-1144)
// ---------------------------------------------------------------------------

/// State identifiers for all animation frames in the game.
