/// S_TECH2LAMP4=966). The sentinel `NUMSTATES` is provided as a separate
/// constant.
///
/// Each variant indexes into the [`STATES`] array to retrieve the
/// corresponding [`State`] struct with sprite, frame, duration, action,
/// and next-state transition data.
