// ---------------------------------------------------------------------------
// State struct (info.h lines 1147-1156)
// ---------------------------------------------------------------------------

/// A single animation frame/state entry.
///
/// Translated from the C `state_t` struct. Each field preserves the exact
/// semantics of the original:
/// - `sprite`: Which sprite to display (indexes sprite name table)
/// - `frame`: Frame number within the sprite; values ORed with 0x8000
///   (32768) indicate the FF_FULLBRIGHT flag (drawn at full brightness
///   regardless of sector light level)
/// - `tics`: Duration in game tics (1/35 second). -1 means infinite
///   (state persists until explicitly changed)
/// - `action`: Action function to call on state entry (None = no action)
/// - `nextstate`: State to transition to after `tics` expire
/// - `misc1`, `misc2`: Auxiliary fields (used by DeHackEd patches)
#[derive(Debug, Clone, Copy)]
pub struct State {
    pub sprite: SpriteNum,
    pub frame: i32,
    pub tics: i32,
    pub action: ActionFnId,
    pub nextstate: StateNum,
    pub misc1: i32,
    pub misc2: i32,
}

